class Node:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def reverse_list(head):
    # Extracts values to list and rebuilds nodes O(N) extra space
    vals = []
    curr = head
    while curr:
        vals.append(curr.val)
        curr = curr.next
    new_head = None
    for v in vals:
        new_head = Node(v, new_head)
    return new_head

